pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, address newOwner) public {
        // Ensure caller is not the current owner (which is address(this) initially from setUp)
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Store the owner before the attempt
        address ownerBefore = c.owner();

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: If the caller is not the owner, the call must revert AND owner must remain unchanged.
        // The bug allows a non-owner to successfully change the owner, violating this invariant.
        assertTrue(!ok && c.owner() == ownerBefore);
    }
}

