pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set an initial owner so that the onlyOwner modifier is satisfied
        vm.prank(address(this));
        c.transferOwnership(address(this));
    }
    function testFuzz_property(address newOwner) public {
        // Admissible domain: any address, including zero address
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            // After a successful transferOwnership call by the current owner:
            // If newOwner is zero, owner remains the current owner (address(this)).
            // If newOwner is non-zero, owner must equal newOwner.
            if (newOwner == address(0)) {
                assertEq(c.owner(), address(this));
            } else {
                assertEq(c.owner(), newOwner);
            }
        } else {
            // The call reverted; owner must not have changed.
            assertEq(c.owner(), address(this));
        }
    }
}

