pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // WIDE admissible domain: exclude the zero address because owner is initially address(0)
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // Ensure caller and newOwner are distinct so the assertion is meaningful
        vm.assume(caller != newOwner);

        // Set the owner to caller so caller is the current owner in the reference
        vm.prank(address(0)); // initial owner is address(0)
        c.transferOwnership(caller);

        vm.prank(caller);
        bool ok = true;
        try c.transferOwnership(newOwner) {}
        catch { ok = false; }

        // Rule: if transferOwnership(newOwner) does not revert when called by caller,
        // then caller must be the current owner, and the new owner must be caller.
        // In the reference, only the owner can call transferOwnership, and it sets owner to newOwner.
        // In the mutant, a non-owner can call transferOwnership and set owner to newOwner.
        // Therefore, the invariant: if ok then c.owner() == newOwner.
        // But wait — the bug is that a non-owner can call transferOwnership. Actually the rule
        // must target the difference: the reference enforces that only the owner can transfer ownership,
        // and the owner becomes newOwner after a successful call. The mutant allows a non-owner to succeed,
        // and the owner becomes newOwner. So the property that fails for the mutant but holds for reference is:
        // if ok, then the caller was the owner at the time of call, i.e., c.owner() == caller before the call.
        // But we cannot observe state before the call in the same assertion easily without storing it.
        // Instead: after a successful transferOwnership(newOwner) by caller, we must have caller == newOwner
        // if caller was not the owner (because in the reference only the owner can call it, so if caller is not owner
        // the call reverts; in the mutant, a non-owner can call it and set owner to newOwner, so after a successful call
        // owner might be newOwner even though caller != newOwner).
        // Simpler: the reference ensures that if the call succeeds, then the previous owner was caller, and the new owner is newOwner.
        // We can encode that as: if ok, then c.owner() == newOwner AND the previous owner was caller.
        // But we cannot check previous owner. However, we can set up so that caller is the current owner,
        // so in the reference the call succeeds and owner becomes newOwner. In the mutant, if caller is owner,
        // the call reverts because require(msg.sender != owner) fails. So the difference is:
        // Reference: caller == owner -> ok and c.owner() == newOwner
        // Mutant: caller == owner -> revert (ok false)
        // But we want a single assertion that the reference always satisfies and the mutant breaks for some input.
        // If we make caller the owner, reference succeeds (ok true) and then c.owner() == newOwner.
        // Mutant reverts (ok false) so assertion about c.owner() is irrelevant.
        // However, the fuzzer can pick any caller, not just the owner. We need a property that holds for every caller.
        // Let's think: after the call, if ok is true, then in the reference caller must have been owner, and c.owner() == newOwner.
        // In the mutant, ok can be true even if caller is not owner, and then c.owner() == newOwner.
        // So the invariant: ok => c.owner() == newOwner holds in BOTH! That's not distinguishing.
        // The difference is in who can cause ok. The reference allows ok only when caller == owner. The mutant allows ok when caller != owner.
        // So the property: "if caller != owner, then !ok" holds for reference but fails for mutant.
        // We can check: if (caller != owner before call) then ok must be false. But owner before call is not observable after call.
        // However, we can arrange so that caller != c.owner() before call by setting owner to someone else.
        // Let's set owner to an initial owner that is neither caller nor newOwner, then have caller call transferOwnership.
        // Reference reverts (ok false). Mutant succeeds (ok true) and c.owner() == newOwner.
        // Property: if caller != owner_before_call, then ok must be false. But we need to assert something that always holds.
        // We can assert: ok implies that caller was owner_before_call. But we cannot check owner_before_call directly.
        // Instead, we can store the owner before the call: address oldOwner = c.owner(); then after call, assert !ok || (oldOwner == caller && c.owner() == newOwner);
        // This holds for every input in the reference: if ok, then oldOwner == caller and c.owner() == newOwner.
        // In the mutant, when caller is not oldOwner, ok can be true, so the assertion fails because oldOwner != caller.
        // So we can do that.

        address oldOwner = c.owner();
        assertTrue(!ok || (oldOwner == caller && c.owner() == newOwner));
    }
}

