import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        // 1. Ensure caller is not the zero address (optional, keeps domain wide)
        vm.assume(caller != address(0));

        // 2. Make the fuzzed caller the owner to trigger the difference.
        //    We prank the current owner (deployer) to transfer ownership to the fuzzed caller.
        vm.prank(address(this)); // deployer is the initial owner
        c.transferOwnership(caller);

        // Now 'caller' is the owner. Drive the target function owned() as the owner.
        vm.prank(caller);
        bool success;
        try c.owned() {
            success = true;
        } catch {
            success = false;
        }

        // 3. Assert the general rule: if the call succeeded, the caller must be the owner.
        //    Reference C (correct): when caller is owner, it succeeds, so success => caller == owner holds (true).
        //    Buggy M: when caller is owner, it reverts, so success is false. The implication success => (caller == owner)
        //    is vacuously true as well! We need a stronger rule that *also* fails on the buggy version.
        //    The invariant that the correct contract guarantees is: "if caller is the owner, the call does not revert".
        //    In logical form: (caller == owner) => success.
        assertTrue(!(caller == c.owner()) || success);
    }
}

